import { Table, useTableController } from '@tale-ui/react/table';

const people = Array.from({ length: 10_000 }, (_, index) => ({
  id: `person-${index + 1}`,
  name: `Person ${index + 1}`,
  role: index % 2 === 0 ? 'Editor' : 'Viewer',
}));

export function VirtualizedPeopleTable() {
  const controller = useTableController({
    tableId: 'virtual-people',
    virtualizationOptions: { rowHeight: 44 },
  });

  return (
    <div style={{ height: 400 }}>
      <Table.Virtualizer {...controller.virtualization.virtualizerProps}>
        <Table.Root aria-label="10,000 people">
          <Table.Header>
            <Table.Column isRowHeader>Name</Table.Column>
            <Table.Column>Role</Table.Column>
          </Table.Header>
          <Table.Body items={people}>
            {(person) => (
              <Table.Row id={person.id}>
                <Table.Cell>{person.name}</Table.Cell>
                <Table.Cell>{person.role}</Table.Cell>
              </Table.Row>
            )}
          </Table.Body>
        </Table.Root>
      </Table.Virtualizer>
    </div>
  );
}
